INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5a-z16-q60','nism-5a-z16','An investor invests ₹1,68,000 in an open-ended scheme at an NAV of ₹81.50. With no entry load, the number of units allotted is:','["2015.990","16800.000","13692000.000","2061.350"]',3,'Units = 168000 ÷ 81.50 = 2061.350.',60) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
