INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5a-z16-q62','nism-5a-z16','An NAV rising from ₹12 to ₹15 gives a simple return of:','["25%","15%","30%","20%"]',0,'(15 − 12) ÷ 12 = 25%.',62) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
